  <body>
    <div id="app"></div>

    <script>
      function createElement(tag, props) {
        const el = document.createElement(tag);
        if (props) {
          Object.entries(props).forEach(([key, value]) => {
            if (key === "className") el.className = value;
            else if (key === "textContent") el.textContent = value;
            else if (key === "htmlFor") el.htmlFor = value;
            else if (key === "children" && Array.isArray(value)) value.forEach((child) => child && el.appendChild(child));
            else if (key.startsWith("on") && typeof value === "function") el.addEventListener(key.slice(2).toLowerCase(), value);
            else if (value !== false && value != null) el.setAttribute(key, value === true ? "" : value);
          });
        }
        return el;
      }

      function FormField({ id, label, type, placeholder, required, autocomplete, helperText }) {
        const field = createElement("div", { className: "form-field" });
        const labelEl = createElement("label", { htmlFor: id, textContent: label + (required ? " *" : "") });
        const input = createElement("input", {
          id,
          name: id,
          type,
          placeholder,
          required: required ? "" : null,
          autocomplete,
        });
        field.append(labelEl, input);
        if (helperText) {
          field.appendChild(createElement("p", { className: "helper-text", textContent: helperText }));
        }
        return { field, input };
      }

      function App() {
        const root = createElement("main", { className: "page" });
        const card = createElement("section", { className: "card", "aria-labelledby": "form-title" });
        const eyebrow = createElement("p", { className: "eyebrow", textContent: "Support" });
        const title = createElement("h1", { id: "form-title", textContent: "Contact our team" });
        const lead = createElement("p", {
          className: "lead",
          textContent: "Send us your details and we will follow up as soon as possible.",
        });

        const form = createElement("form", { novalidate: "" });
        const nameField = FormField({
          id: "full-name",
          label: "Full name",
          type: "text",
          placeholder: "Jane Doe",
          required: true,
          autocomplete: "name",
        });
        const emailField = FormField({
          id: "email-address",
          label: "Email address",
          type: "email",
          placeholder: "jane@example.com",
          required: true,
          autocomplete: "email",
        });
        const phoneField = FormField({
          id: "phone-number",
          label: "Phone number",
          type: "tel",
          placeholder: "+1 555 123 4567",
          required: false,
          autocomplete: "tel",
          helperText: "Optional. Include your country code if possible, for example +1 555 123 4567.",
        });

        const status = createElement("div", { className: "success", hidden: "" });
        const submit = createElement("button", { type: "submit", textContent: "Send message" });

        const inputs = [nameField.input, emailField.input, phoneField.input];
        const fields = [nameField.field, emailField.field, phoneField.field];

        function renderErrors(showErrors) {
          fields.forEach((field) => {
            const existing = field.querySelector(".error-text");
            if (existing) existing.remove();
            field.classList.remove("field-invalid");
          });

          if (!showErrors) return false;

          let hasError = false;
          inputs.forEach((input, index) => {
            if (!input.validity.valid) {
              hasError = true;
              fields[index].classList.add("field-invalid");
              const message = createElement("p", { className: "error-text" });
              if (input.validity.valueMissing) message.textContent = "This field is required.";
              else if (input.validity.typeMismatch && input.type === "email") message.textContent = "Enter a valid email address.";
              else message.textContent = "Please enter a valid value.";
              fields[index].appendChild(message);
            }
          });

          return hasError;
        }

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          status.hidden = true;
          const hasError = renderErrors(true);
          if (hasError) return;
          status.textContent = "Thanks — your message has been prepared for submission.";
          status.hidden = false;
          form.reset();
        });

        inputs.forEach((input) => {
          input.addEventListener("input", () => {
            if (input.checkValidity()) {
              const field = input.closest(".form-field");
              field.classList.remove("field-invalid");
              const error = field.querySelector(".error-text");
              if (error) error.remove();
            }
          });
        });

        form.append(nameField.field, emailField.field, phoneField.field, submit, status);
        card.append(eyebrow, title, lead, form);
        root.appendChild(card);
        return root;
      }

